package servers

import (
	"context"
	"fmt"
	"net/netip"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
	"time"

	"github.com/BROadmin/broray/modules/reserve"
)

// The record protocol and Xray outbound protocol differ for Hysteria2.
// Exercise the generated bytes, the reserve extension and the pinned Core together.
func TestReserveHysteriaNativeConfiguration(t *testing.T) {
	bin := os.Getenv("BRORAY_XRAY_BIN")
	if bin == "" {
		t.Skip("BRORAY_XRAY_BIN not set")
	}
	for _, host := range []string{"127.0.0.1", "[::1]"} {
		t.Run(host, func(t *testing.T) {
			rec, err := ParseLink(fmt.Sprintf("hy2://synthetic@%s:443?sni=localhost#B", host), "hysteria-reserve", nil)
			if err != nil {
				t.Fatal(err)
			}
			cfg, err := XrayConfig(rec, GenSettings{Listen: "127.0.0.1", SocksPort: 2080, LogLevel: "none"}, "hysteria-reserve")
			if err != nil {
				t.Fatal(err)
			}
			endpoint := netip.MustParseAddrPort("127.0.0.1:32080")
			got, err := reserve.AttachHealthInbound(cfg, endpoint)
			if err != nil {
				t.Fatalf("generated Hysteria2 profile cannot retain reserve diagnostic path: %v", err)
			}
			if observed, ok := reserve.DiagnosticEndpoint(got); !ok || observed != endpoint {
				t.Fatal("diagnostic roundtrip lost")
			}
			path := filepath.Join(t.TempDir(), "client.json")
			if err := os.WriteFile(path, got, 0600); err != nil {
				t.Fatal(err)
			}
			ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
			defer cancel()
			output, err := exec.CommandContext(ctx, bin, "run", "-test", "-config", path).CombinedOutput()
			if err != nil {
				t.Fatalf("native Core rejected generated reserve profile: %v\n%s", err, output)
			}
		})
	}
}
